 }
+
+// ExecAttached runs a command in the container of the one node the list options select, with
+// stdin, an optional TTY and terminal resizing, like docker exec -it. A command exiting nonzero
+// returns a *labruntime.CommandExitError. With Docker and clabernetes, a command that can't
+// start, such as a missing executable, returns an error without writing any output; Podman
+// reports its exit code. Podman also sizes the terminal from containerlab's own terminal and
+// ignores streams.Resize, and clabernetes applies the first size just after the command started.
+//
+// Stdin is read until it ends, which can outlast the call, so callers end it (for example by
+// closing a pipe) once the session is over. With Docker, the end of stdin or the detach keys
+// (ctrl-p, ctrl-q) end a terminal session without ending the command, which returns an error.
+func (c *CLab) ExecAttached(
+	ctx context.Context,
+	cmd []string,
+	tty bool,
+	streams clablabruntime.AttachStreams,
+	listOptions ...ListOption,
+) error {
+	if len(cmd) == 0 {
+		return errors.New("an attached exec needs a command")
+	}
+
+	if c.LabRuntime != nil {
+		containers, err := c.ListLabRuntimeContainers(ctx, false, listOptions...)
+		if err != nil {
+			return err
+		}
+
+		target, err := attachedExecTarget(containers)
+		if err != nil {
+			return err
+		}
+
+		namespace, labName, nodeName, err := labRuntimeContainerParts(*target)
+		if err != nil {
+			return fmt.Errorf("exec target %s is invalid: %w", target.Names[0], err)
+		}
+
+		return c.AttachLabRuntimeNode(ctx, clablabruntime.AttachRequest{
+			Name:      labName,
+			Namespace: namespace,
+			NodeName:  nodeName,
+			Command:   cmd,
+			TTY:       tty,
+		}, streams)
+	}
+
+	containers, err := c.ListContainers(ctx, listOptions...)
+	if err != nil {
+		return err
+	}
+
+	target, err := attachedExecTarget(containers)
+	if err != nil {
+		return err
+	}
+
+	attacher, ok := target.Runtime.(clabruntime.ContainerAttacher)
+	if !ok {
+		return fmt.Errorf("container runtime %q does not support attached exec",
+			target.Runtime.GetName())
+	}
+
+	return attacher.AttachContainer(ctx, target.Names[0], cmd, tty, streams)
+}
+
+// attachedExecTarget returns the container of an attached exec, which needs the filter to match
+// exactly one.
+func attachedExecTarget(
+	containers []clabruntime.GenericContainer,
+) (*clabruntime.GenericContainer, error) {
+	switch len(containers) {
+	case 0:
+		return nil, fmt.Errorf("filter did not match any containers")
+	case 1:
+		return &containers[0], nil
+	}
+
+	return nil, fmt.Errorf(
+		"an attached exec needs a filter matching exactly one container, the filter matched %d",
+		len(containers))
+}
diff --git a/core/exec_test.go b/core/exec_test.go
new file mode 100644
index 0000000..0774a51
--- /dev/null
+++ b/core/exec_test.go
@@ -0,0 +1,184 @@
+package core
+
+import (
+	"context"
+	"errors"
+	"io"
+	"strings"
+	"testing"
+
+	"github.com/google/go-cmp/cmp"
+	clabconstants "github.com/srl-labs/containerlab/constants"
+	clablabruntime "github.com/srl-labs/containerlab/labruntime"
+	clabmocksmockruntime "github.com/srl-labs/containerlab/mocks/mockruntime"
+	clabruntime "github.com/srl-labs/containerlab/runtime"
+	clabtypes "github.com/srl-labs/containerlab/types"
+	"go.uber.org/mock/gomock"
+)
+
+// attachingLabRuntime records the attach request of an attached exec on a lab runtime.
+type attachingLabRuntime struct {
+	clablabruntime.LabRuntime
+
+	request clablabruntime.AttachRequest
+	exitErr error
+}
+
+func (r *attachingLabRuntime) Inspect(
+	context.Context,
+	clablabruntime.InspectRequest,
+) (*clablabruntime.LabState, error) {
+	return &clablabruntime.LabState{
+		Name:      "lab1",
+		Namespace: "lab-ns",
+		Nodes:     []clablabruntime.NodeState{{Name: "node1"}, {Name: "node2"}},
+	}, nil
+}
+
+func (r *attachingLabRuntime) Attach(
+	_ context.Context,
+	req clablabruntime.AttachRequest,
+	streams clablabruntime.AttachStreams,
+) error {
+	r.request = req
+
+	if _, err := io.Copy(streams.Stdout, streams.Stdin); err != nil {
+		return err
+	}
+
+	return r.exitErr
+}
+
+func TestExecAttachedWithALabRuntime(t *testing.T) {
+	t.Parallel()
+
+	runtime := &attachingLabRuntime{exitErr: &clablabruntime.CommandExitError{Code: 3}}
+	c := &CLab{
+		Config:             &Config{Name: "lab1", Topology: clabtypes.NewTopology()},
+		TopoPaths:          &clabtypes.TopoPaths{},
+		LabRuntime:         runtime,
+		globalRuntimeName:  clablabruntime.ClabernetesRuntimeName,
+		labRuntimeIdentity: testIdentity,
+	}
+
+	var stdout strings.Builder
+	err := c.ExecAttached(context.Background(), []string{"sh", "-c", "cat > /tmp/f"}, true,
+		clablabruntime.AttachStreams{Stdin: strings.NewReader("config"), Stdout: &stdout},
+		WithListFromCliArgs([]string{clabconstants.NodeName + "=node1"}))
+
+	var exitErr *clablabruntime.CommandExitError
+	if !errors.As(err, &exitErr) || exitErr.Code != 3 {
+		t.Fatalf("ExecAttached() error = %v, want the command's exit code 3", err)
+	}
+	want := clablabruntime.AttachRequest{
+		Name:      "lab1",
+		Namespace: "lab-ns",
+		NodeName:  "node1",
+		Command:   []string{"sh", "-c", "cat > /tmp/f"},
+		TTY:       true,
+		Identity:  testIdentity,
+	}
+	if d := cmp.Diff(want, runtime.request); d != "" {
+		t.Fatalf("attach request mismatch (-want +got):\n%s", d)
+	}
+	if stdout.String() != "config" {
+		t.Fatalf("stdin reached the command as %q", stdout.String())
+	}
+
+	err = c.ExecAttached(context.Background(), []string{"sh"}, false, clablabruntime.AttachStreams{})
+	if err == nil || !strings.Contains(err.Error(), "matched 2") {
+		t.Fatalf("ExecAttached() on two nodes error = %v", err)
+	}
+}
+
+// attachingRuntime adds the optional attacher to the container runtime mock.
+type attachingRuntime struct {
+	*clabmocksmockruntime.MockContainerRuntime
+
+	containerName string
+	cmd           []string
+	tty           bool
+}
+
+func (r *attachingRuntime) AttachContainer(
+	_ context.Context,
+	containerName string,
+	cmd []string,
+	tty bool,
+	streams clablabruntime.AttachStreams,
+) error {
+	r.containerName = containerName
+	r.cmd = cmd
+	r.tty = tty
+	_, err := io.Copy(streams.Stdout, streams.Stdin)
+
+	return err
+}
+
+func TestExecAttachedWithALocalRuntime(t *testing.T) {
+	t.Parallel()
+
+	ctrl := gomock.NewController(t)
+	mock := clabmocksmockruntime.NewMockContainerRuntime(ctrl)
+	runtime := &attachingRuntime{MockContainerRuntime: mock}
+
+	mock.EXPECT().ListContainers(gomock.Any(), gomock.Any()).DoAndReturn(
+		func(_ context.Context, filters []*clabtypes.GenericFilter) (
+			[]clabruntime.GenericContainer, error,
+		) {
+			containers := []clabruntime.GenericContainer{
+				{Names: []string{"clab-lab1-r1"}, Runtime: runtime},
+				{Names: []string{"clab-lab1-r2"}, Runtime: runtime},
+			}
+			for _, filter := range filters {
+				if filter.Field == clabconstants.NodeName {
+					return containers[:1], nil
+				}
+			}
+
+			return containers, nil
+		}).
+		AnyTimes()
+
+	c := &CLab{
+		Config:   &Config{Name: "lab1"},
+		Runtimes: map[string]clabruntime.ContainerRuntime{"docker": runtime},
+	}
+
+	var stdout strings.Builder
+	if err := c.ExecAttached(context.Background(), []string{"bash"}, true,
+		clablabruntime.AttachStreams{Stdin: strings.NewReader("exit\n"), Stdout: &stdout},
+		WithListFromCliArgs([]string{clabconstants.NodeName + "=r1"})); err != nil {
+		t.Fatal(err)
+	}
+	if runtime.containerName != "clab-lab1-r1" || len(runtime.cmd) != 1 ||
+		runtime.cmd[0] != "bash" || !runtime.tty || stdout.String() != "exit\n" {
+		t.Fatalf("container %q cmd %q tty %t stdout %q",
+			runtime.containerName, runtime.cmd, runtime.tty, stdout.String())
+	}
+
+	err := c.ExecAttached(context.Background(), []string{"bash"}, false, clablabruntime.AttachStreams{})
+	if err == nil || !strings.Contains(err.Error(), "matched 2") {
+		t.Fatalf("ExecAttached() on two containers error = %v", err)
+	}
+}
+
+func TestExecAttachedWithoutAnAttachingRuntime(t *testing.T) {
+	t.Parallel()
+
+	ctrl := gomock.NewController(t)
+	mock := clabmocksmockruntime.NewMockContainerRuntime(ctrl)
+	mock.EXPECT().GetName().Return("docker").AnyTimes()
+	mock.EXPECT().ListContainers(gomock.Any(), gomock.Any()).Return(
+		[]clabruntime.GenericContainer{{Names: []string{"clab-lab1-r1"}, Runtime: mock}}, nil)
+
+	c := &CLab{
+		Config:   &Config{Name: "lab1"},
+		Runtimes: map[string]clabruntime.ContainerRuntime{"docker": mock},
+	}
+
+	err := c.ExecAttached(context.Background(), []string{"bash"}, false, clablabruntime.AttachStreams{})
+	if err == nil || !strings.Contains(err.Error(), "does not support attached exec") {
+		t.Fatalf("ExecAttached() error = %v", err)
+	}
+}
diff --git a/docs/cmd/exec.md b/docs/cmd/exec.md
index 600a7e8..1a047a0 100644
--- a/docs/cmd/exec.md
+++ b/docs/cmd/exec.md
@@ -38,10 +38,22 @@ The command to be executed on the nodes is provided with `--cmd` flag. The comma

 The `--format | -f` flag allows selecting between plain text format output or a json variant. Consult with the examples below to see the differences between these two formatting options.

 Defaults to `plain` output format.

+### stdin
+
+With the `--stdin | -i` flag the command gets containerlab's stdin, like `docker exec -i`, for example to copy a file into a node. The output of the command is written to stdout and stderr as it comes, and containerlab exits with the command's exit code. A command that can't start, such as a missing executable, is reported as an error with the Docker and clabernetes runtimes, and containerlab exits with 1.
+
+The filter must then match exactly one node, and `--cmd` can be given once. `--format` is not supported with `--stdin` and `--tty`.
+
+### tty
+
+The `--tty` flag runs the command in a terminal, like `docker exec -t`; its output goes to stdout. Together with `--stdin` it opens an interactive session, for which containerlab's stdin must be a terminal. The same rules as for `--stdin` apply.
+
+With Docker, the detach keys `ctrl-p`, `ctrl-q` leave an interactive session like with `docker exec`; the command keeps running and containerlab exits with an error. With Podman, `--tty` from a terminal needs `--stdin`, as Podman connects the session to containerlab's terminal.
+
 ### label

 Using `--label` it is possible to filter the nodes to execute the command on using labels attached to the nodes. The label is provided as a string in the form of `key=value`. The `key` is the label name, and the `value` is the label value.

 Exec command should either be provided with a topology file, or labels, or both.
